"""docs/portfolio/FACTS.md is generated by scripts/portfolio_facts.py from the
repository at a pinned commit: a hand edit, or a source whose value at the pin
changed, fails here. Skipped when the pinned commit is not in the checkout."""

from __future__ import annotations

import importlib.util
import re
import subprocess
import tempfile
import unittest
from pathlib import Path
from unittest import mock

REPO = Path(__file__).resolve().parents[1]
_spec = importlib.util.spec_from_file_location(
    "portfolio_facts", REPO / "scripts" / "portfolio_facts.py"
)
pf = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(pf)

PINNED = (
    subprocess.run(
        ["git", "-C", str(REPO), "cat-file", "-e", f"{pf.PIN}^{{commit}}"],
        capture_output=True,
        check=False,
    ).returncode
    == 0
)


@unittest.skipUnless(PINNED, f"{pf.PIN} is not in this checkout (shallow clone)")
class PortfolioFactsTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.text = pf.build()

    def test_the_committed_facts_are_a_regeneration(self) -> None:
        self.assertEqual(
            pf.OUT.read_text(encoding="utf-8"),
            self.text,
            "docs/portfolio/FACTS.md is stale or hand-edited: run python scripts/portfolio_facts.py",
        )

    def test_check_fails_on_a_hand_edit(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            out = Path(tmp) / "FACTS.md"
            with mock.patch.object(pf, "OUT", out):
                self.assertEqual(pf.main([]), 0)
                self.assertEqual(pf.main(["--check"]), 0)
                out.write_text(
                    self.text.replace("+27,18 %", "+37,18 %", 1), encoding="utf-8"
                )
                self.assertEqual(pf.main(["--check"]), 1)

    def test_every_fact_is_typed_and_sourced(self) -> None:
        facts = pf.facts()
        self.assertTrue(15 <= len(facts) <= 25)
        for title, kind, value, meaning, source in facts:
            self.assertIn(kind, pf.TYPES, title)
            self.assertTrue(value and meaning and source, title)

    def test_the_losing_side_comes_first(self) -> None:
        self.assertIn("o H1 nunca rodou", self.text)
        self.assertIn("fatos prospectivos: 0", self.text)
        first = next(ln for ln in self.text.splitlines() if ln.startswith("| 1 |"))
        self.assertIn("não rodou: 0 arquivos `cells.csv`", first)

    def test_values_match_outputs_written_by_other_code(self) -> None:
        """Independent oracles: numbers that other scripts and documents wrote at the
        pin, not this generator's formulas."""
        prereg = pf.show("docs/PREREGISTRATION.md")
        n = re.search(r"C\(8, 3\) = (\d+) ways", prereg).group(1)
        self.assertIn(f"{n} rotulações", self.text)
        surv = pf.show("benchmark/results/survivorship/README.md")
        gap = re.search(r"across 20 cells: \*\*\+([\d.]+)\*\* pp", surv).group(1)
        self.assertIn(f"+{gap.replace('.', ',')} pp em média", self.text)
        hmm = pf.show("benchmark/results/hmm_regimes/README.md")
        purity = re.search(r"four hand windows = ([\d.]+)\.\*\*", hmm).group(1)
        self.assertIn(f"pureza ponderada {purity.replace('.', ',')}", self.text)
        chronos = pf.show("benchmark/results/chronos/README.md")
        cr = re.search(r"chronos\s+PETR4\s+([\d.]+)", chronos).group(1)
        self.assertIn(f"retorno médio +{float(cr):.2f} %".replace(".", ","), self.text)

    def test_counts_carry_their_denominator(self) -> None:
        rows = [ln for ln in self.text.splitlines() if re.match(r"\| \d+ \|", ln)]
        self.assertEqual(len(rows), len(pf.facts()))
        for row in rows:
            value = row.split(" | ")[2]
            if any(w in value for w in ("feitos", "regeneradas", "células", "datas")):
                self.assertRegex(value, r"\b\d+ de \d+\b", value)


if __name__ == "__main__":
    unittest.main()
